CREATE OR REPLACE FUNCTION business_auth.device(p_business uuid, p_device text, p_proof text, p_label text, p_bootstrap boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.business_devices%rowtype;k business_auth.device_keys%rowtype;
begin
 if p_device is null or p_device !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or p_proof is null or p_proof !~ '^[0-9a-f]{64}$' or length(coalesce(p_label,''))>100 then
  return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 select * into d from public.business_devices where business_id=p_business and device_id=p_device for update;
 if found then
  select * into k from business_auth.device_keys where device_id=d.id;
  -- A legacy registration or changed browser secret requires explicit review;
  -- knowledge of a device ID is never enough to take over that registration.
  if k.device_id is null or k.proof_hash<>p_proof then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
  if k.revoked_at is not null then return jsonb_build_object('allowed',false,'error','DEVICE_BLOCKED');end if;
  if d.status<>'approved' then return jsonb_build_object('allowed',false,'error','DEVICE_APPROVAL_REQUIRED');end if;
 else
  if (select count(*) from public.business_devices where business_id=p_business)>=200 then return jsonb_build_object('allowed',false,'error','DEVICE_LIMIT');end if;
  insert into public.business_devices(business_id,device_id,label,status,approved_at)
   values(p_business,p_device,nullif(btrim(p_label),''),case when p_bootstrap then 'approved' else 'pending' end,case when p_bootstrap then clock_timestamp() end)
   returning * into d;
  insert into business_auth.device_keys(device_id,proof_hash) values(d.id,p_proof);
  insert into business_auth.events(business_id,device_id,action) values(p_business,d.id,case when p_bootstrap then 'owner_device_bootstrapped' else 'device_approval_requested' end);
  if not p_bootstrap then return jsonb_build_object('allowed',false,'error','DEVICE_APPROVAL_REQUIRED');end if;
 end if;
 return jsonb_build_object('allowed',true,'device_id',d.id);
end $function$

CREATE OR REPLACE FUNCTION business_auth.revoke_device_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' or new.status<>'approved' then
  delete from auth.sessions where id in(select session_id from business_auth.sessions where device_id=old.id);
  update business_auth.grants set expires_at=least(expires_at,clock_timestamp()) where device_id=old.id;
  update business_auth.device_keys set revoked_at=coalesce(revoked_at,clock_timestamp()) where device_id=old.id;
 else update business_auth.device_keys set revoked_at=null where device_id=old.id;end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION business_auth.revoke_member_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' or not new.active or new.code_hash is distinct from old.code_hash then
  delete from auth.sessions where id in(select session_id from business_auth.sessions where member_id=old.id);
  update business_auth.grants set expires_at=least(expires_at,clock_timestamp()) where member_id=old.id;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION business_auth.revoke_owner_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if old.role='owner' and (tg_op='DELETE' or new.role<>'owner' or new.business_id<>old.business_id or new.member_id<>old.member_id) then
  delete from auth.sessions where id in(select session_id from business_auth.sessions where business_id=old.business_id and principal_user_id=old.member_id);
  update public.business_access_members set active=false where id in(select member_id from business_auth.owner_seats where business_id=old.business_id and user_id=old.member_id);
  update business_auth.grants set expires_at=least(expires_at,clock_timestamp()) where business_id=old.business_id and principal_user_id=old.member_id;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.business_session_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();sid uuid;
begin
 if uid is null then return true;end if;
 if not exists(select 1 from business_auth.accounts where business_id=uid)
  and not exists(select 1 from public.profiles where id=uid and account_type='business') then return true;end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid;exception when others then return false;end;
 return business_auth.session_allowed(uid,sid);
end $function$

CREATE OR REPLACE FUNCTION public.resolve_media_delivery(p_token text, p_bucket text, p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g media_delivery.tickets%rowtype; allowed boolean:=false;
 old_sub text:=coalesce(current_setting('request.jwt.claim.sub',true),'');
 old_role text:=coalesce(current_setting('request.jwt.claim.role',true),'');
 old_claims text:=coalesce(current_setting('request.jwt.claims',true),'');
begin
 if p_token is null or p_token !~ '^[0-9a-f]{64}$' then return null;end if;
 select * into g from media_delivery.tickets where token_digest=extensions.digest(p_token,'sha256')
  and bucket_id=p_bucket and object_path=p_path and expires_at>clock_timestamp();
 if not found or not exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.id=g.session_id and s.user_id=g.user_id
  and (s.not_after is null or s.not_after>clock_timestamp()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=clock_timestamp()))
  or not exists(select 1 from storage.objects o where o.id=g.object_id and o.bucket_id=g.bucket_id and o.name=g.object_path
   and o.version=g.object_version and coalesce(o.owner_id,o.owner::text) is not distinct from g.object_owner) then return null;end if;
 perform set_config('request.jwt.claim.sub',g.user_id::text,true),set_config('request.jwt.claim.role','authenticated',true),
  set_config('request.jwt.claims',jsonb_build_object('sub',g.user_id,'role','authenticated','session_id',g.session_id,'is_anonymous',false)::text,true);
 if g.source_kind='upload' then
  select exists(select 1 from public.content_upload_manifest(jsonb_build_array(g.source_url)) m where m.media_url=g.source_url) into allowed;
 elsif g.source_kind='chat' then
  select exists(select 1 from public.chat_media_manifest(array[g.source_id]) m where m.view_limit is null and g.source_url in(m.media_url,m.thumbnail_url)) into allowed;
 elsif g.source_kind='chat_object' then
  allowed:=g.object_owner=g.user_id::text or (public.chat_locator_unrestricted(g.bucket_id||'/'||g.object_path)
   and (public.can_read_chat_object(g.bucket_id,g.object_path) or public.can_read_legacy_chat_object(g.bucket_id,g.object_path)));
 else
  select exists(select 1 from public.content_media_manifest(jsonb_build_array(jsonb_build_object('kind',g.source_kind,'id',g.source_id))) m where m.media_url=g.source_url) into allowed;
 end if;
 perform set_config('request.jwt.claim.sub',old_sub,true),set_config('request.jwt.claim.role',old_role,true),set_config('request.jwt.claims',old_claims,true);
 if not coalesce(allowed,false) or (exists(select 1 from business_auth.accounts where business_id=g.user_id) and not business_auth.session_allowed(g.user_id,g.session_id)) then return null;end if;
 return jsonb_build_object('bucket',g.bucket_id,'path',g.object_path,'version',g.object_version,'expiresAt',g.expires_at);
exception when others then
 perform set_config('request.jwt.claim.sub',old_sub,true),set_config('request.jwt.claim.role',old_role,true),set_config('request.jwt.claims',old_claims,true);
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.studio_bind_member(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a studio_workflow.actor:=studio_workflow.context();m public.business_access_members%rowtype;
begin
 if not a.is_business or a.member_id is null or length(coalesce(p_code,'')) not between 4 and 200 then
  raise exception 'BUSINESS_SIGNIN_REQUIRED' using errcode='42501';end if;
 select * into m from public.business_access_members where id=a.member_id and business_id=a.user_id and active
  and upper(code_hash)=upper(encode(extensions.digest(upper(btrim(p_code)),'sha256'),'hex'));
 if not found then raise exception 'BUSINESS_SEAT_SWITCH_REQUIRES_SIGNIN' using errcode='42501';end if;
 return jsonb_build_object('member_id',m.id,'role',m.role,'display_name',m.display_name);
end $function$

CREATE OR REPLACE FUNCTION public.studio_role()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();sid uuid;is_business boolean;r text;
begin
 if uid is null or coalesce(auth.jwt()->>'is_anonymous','false')<>'false' then return null;end if;
 if not public.business_session_allowed() then return null;end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid;exception when others then return null;end;
 if not exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.id=sid and s.user_id=uid
  and (s.not_after is null or s.not_after>now()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()))
  or exists(select 1 from account_erasure.jobs where user_id=uid and state<>'completed')
  or exists(select 1 from admin_ops.staff_social_shells where user_id=uid) then return null;end if;
 select coalesce(account_type='business',false) into is_business from public.profiles where id=uid and deactivated_at is null;
 if not found then return null;end if;
 if not is_business or not exists(select 1 from public.business_access_members where business_id=uid) then return 'owner';end if;
 select m.role into r from public.studio_session_members s join public.business_access_members m on m.id=s.member_id and m.business_id=s.business_id
  where s.session_id=sid::text and s.business_id=uid and m.active;
 return case when r in ('owner','admin','editor','recruiter','support') then r else null end;
end $function$

CREATE OR REPLACE FUNCTION public.studio_set_device(p_device uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a studio_workflow.actor;d public.business_devices%rowtype;
begin
 if auth.uid() is null then raise exception 'WORKFLOW_ACTIVE_SESSION_REQUIRED' using errcode='42501';end if;
 perform account_erasure.assert_writable(auth.uid());
 perform pg_advisory_xact_lock(hashtextextended('studio-access:'||auth.uid()::text,0));
 a:=studio_workflow.context();
 perform studio_workflow.require_roles(a,array['owner','admin']);
 if p_action not in ('approve','remove') then raise exception 'WORKFLOW_INVALID_ACTION';end if;
 select * into d from public.business_devices where id=p_device and business_id=a.user_id for update;
 if not found then raise exception 'WORKFLOW_DEVICE_UNAVAILABLE';end if;
 -- Keep a rejected registration as pending. Deleting the last registration
 -- could cause an old sign-in flow to trust it as a new first device again.
 update public.business_devices set status=case when p_action='approve' then 'approved' else 'pending' end,
  approved_at=case when p_action='approve' then clock_timestamp() end where id=d.id;
 insert into studio_workflow.access_events(owner_id,actor_member_id,target_id,action,before_state,after_state)
 values(a.user_id,a.member_id,d.id,'device_'||p_action,jsonb_build_object('status',d.status),
  jsonb_build_object('status',case when p_action='approve' then 'approved' else 'pending' end));
end $function$

CREATE OR REPLACE FUNCTION public.triniti_admin_provision(p_actor_id uuid, p_session_id uuid, p_key uuid, p_kind text, p_payload jsonb, p_phase text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j admin_ops.provisions%rowtype; application public.business_applications%rowtype;
 email_value text; username_value text; new_id uuid; snapshot_value jsonb:='{}'::jsonb;
 role_value text; result_value jsonb; auth_user auth.users%rowtype;
begin
 perform pg_advisory_xact_lock(77123,1);
 perform admin_ops.require_session(p_actor_id,p_session_id,case p_kind when 'staff' then 'staff_manage' when 'business' then 'business_manage' else '' end);
 if p_key is null or p_kind not in ('staff','business') or p_phase not in ('reserve','finish') or p_phase is null
  or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>4096 then raise exception 'INVALID_PROVISION'; end if;
 if p_kind='staff' then
  if (select count(*) from jsonb_object_keys(p_payload))<>3 or not p_payload ?& array['email','role','password_digest']
   or exists(select 1 from jsonb_each(p_payload) v where jsonb_typeof(v.value)<>'string') then raise exception 'INVALID_PROVISION'; end if;
  email_value:=lower(btrim(p_payload->>'email')); role_value:=p_payload->>'role';
  if email_value is null or length(email_value)>254 or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
   or p_payload->>'password_digest' !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_PROVISION'; end if;
  if role_value is null or role_value not in ('super_admin','platform_admin','trust_safety','support_agent','ops_engineer','market_reviewer','jobs_reviewer','verification_reviewer','finance_admin','analyst','auditor_readonly') then raise exception 'INVALID_STAFF_ROLE'; end if;
 else
  if (select count(*) from jsonb_object_keys(p_payload))<>1 or jsonb_typeof(p_payload->'id') is distinct from 'string' then raise exception 'INVALID_PROVISION'; end if;
 end if;
 select * into j from admin_ops.provisions where command_key=p_key for update;
 if found then
  if j.actor_id<>p_actor_id or j.kind<>p_kind or j.payload<>p_payload then raise exception 'COMMAND_KEY_REUSED'; end if;
 else
  if p_phase<>'reserve' then raise exception 'PROVISION_NOT_RESERVED'; end if;
  if p_kind='business' then
   select * into application from public.business_applications where id=(p_payload->>'id')::uuid for update;
   if not found then raise exception 'TARGET_NOT_FOUND'; end if;
   if application.status<>'submitted' then raise exception 'APPLICATION_NOT_PENDING'; end if;
   if application.applicant_id is null or not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=application.applicant_id
    and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) for share of p,u) then raise exception 'BUSINESS_OWNER_REQUIRED'; end if;
   username_value:=lower(btrim(application.desired_username));
   if app_routes.is_reserved_username(username_value) then raise exception 'USERNAME_ALREADY_IN_USE';end if;
   if username_value !~ '^[a-z0-9_]{3,32}$' then raise exception 'INVALID_BUSINESS_USERNAME'; end if;
   if exists(select 1 from public.profiles where lower(username)=username_value) then raise exception 'USERNAME_ALREADY_IN_USE'; end if;
   snapshot_value:=jsonb_build_object('applicant_id',application.applicant_id,'company_name',application.company_name,'desired_username',username_value,'category',application.category,'description',application.description,'contact_email',lower(btrim(application.contact_email)));
   -- Business identities are delegated, not extra passwords for the owner's email.
   -- Their contact email stays on the application; the non-deliverable identity
   -- cannot consume or take over an existing personal login.
   new_id:=gen_random_uuid(); email_value:='business+'||new_id::text||'@accounts.platinumcircles.invalid';
  else
   if exists(select 1 from auth.users where lower(email)=email_value) then raise exception 'EMAIL_ALREADY_IN_USE'; end if;
   new_id:=gen_random_uuid();
  end if;
  insert into admin_ops.provisions(command_key,actor_id,kind,payload,auth_user_id,email,application_id,snapshot)
  values(p_key,p_actor_id,p_kind,p_payload,new_id,email_value,case when p_kind='business' then application.id else null end,snapshot_value) returning * into j;
  if p_kind='staff' then
   -- The server generated this fresh UUID; never convert an existing identity.
   if exists(select 1 from auth.users where id=j.auth_user_id)
    or exists(select 1 from public.profiles where id=j.auth_user_id) then
    raise exception 'STAFF_SHELL_IDENTITY_EXISTS';
   end if;
   insert into admin_ops.staff_social_shells(user_id,command_key,provision_id)
   values(j.auth_user_id,j.command_key,j.provision_id);
  end if;
 end if;
 result_value:=jsonb_build_object('success',true,'command_key',p_key,'provision_id',j.provision_id,'auth_user_id',j.auth_user_id,'email',j.email,'complete',j.completed_at is not null);
 if j.completed_at is not null or p_phase='reserve' then return result_value; end if;
 select * into auth_user from auth.users where id=j.auth_user_id for update;
 if not found or auth_user.raw_app_meta_data->>'triniti_provision_id' is distinct from j.provision_id::text
  or lower(auth_user.email) is distinct from j.email or auth_user.deleted_at is not null
  or (j.kind='staff' and auth_user.banned_until>now()) then raise exception 'PROVISION_IDENTITY_MISMATCH'; end if;
 if j.kind='staff' then
  insert into public.profiles(id,email,full_name,account_type) values(j.auth_user_id,j.email,'','personal') on conflict(id) do nothing;
  if exists(select 1 from admin_ops.staff_social_shells where user_id=j.auth_user_id and provision_id=j.provision_id) then
   update public.profiles set deactivated_at=coalesce(deactivated_at,clock_timestamp()),
    profile_visibility='private',push_token=null where id=j.auth_user_id;
  end if;
  insert into public.admin_users(user_id,role,created_by) values(j.auth_user_id,j.payload->>'role',p_actor_id);
 else
  select * into application from public.business_applications where id=j.application_id for update;
  if application.status<>'submitted' then raise exception 'APPLICATION_NOT_PENDING'; end if;
  if application.applicant_id::text is distinct from j.snapshot->>'applicant_id'
   or lower(btrim(application.desired_username)) is distinct from j.snapshot->>'desired_username'
   or application.company_name is distinct from j.snapshot->>'company_name'
   or application.category is distinct from j.snapshot->>'category'
   or application.description is distinct from j.snapshot->>'description'
   or lower(btrim(application.contact_email)) is distinct from j.snapshot->>'contact_email' then raise exception 'APPLICATION_CHANGED'; end if;
  if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=application.applicant_id
    and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) for share of p,u) then raise exception 'BUSINESS_OWNER_REQUIRED'; end if;
  insert into public.profiles(id,email,full_name,username,bio,account_type,account_class,is_verified,verified_tier,verified_category)
  values(j.auth_user_id,j.email,j.snapshot->>'company_name',j.snapshot->>'desired_username',j.snapshot->>'description','business','organization',true,'business',j.snapshot->>'category')
  on conflict(id) do update set full_name=excluded.full_name,username=excluded.username,bio=excluded.bio,account_type='business',account_class='organization',is_verified=true,verified_tier='business',verified_category=excluded.verified_category,updated_at=now();
  insert into public.business_members(business_id,member_id,role) values(j.auth_user_id,application.applicant_id,'owner');
  update public.business_applications set status='approved',decided_by=p_actor_id,decided_at=now(),decision_reason=null where id=application.id;
  -- A business account is controlled through delegated membership, not sign-in.
  -- The random-password, non-deliverable business identity opens only through a bound member/device session. Existing banned identities are never enabled here.
 end if;
 insert into public.admin_audit_log(admin_id,action,target_kind,target_id,after)
 values(p_actor_id,case when j.kind='staff' then 'inviteStaff' else 'approveBusinessApplication' end,j.kind,j.auth_user_id::text,
  jsonb_build_object('provision_id',j.provision_id,'application_id',j.application_id,'role',j.payload->>'role'));
 update admin_ops.provisions set completed_at=now() where command_key=p_key;
 return result_value||jsonb_build_object('complete',true);
end $function$

CREATE OR REPLACE FUNCTION public.triniti_business_cancel_signin(p_grant_id uuid, p_business_id uuid, p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g business_auth.grants%rowtype;
begin
 select * into g from business_auth.grants where id=p_grant_id and business_id=p_business_id for update;
 if not found then return false;end if;
 if exists(select 1 from auth.sessions where id=p_session_id and user_id=g.business_id and created_at>=g.created_at-interval '2 seconds')
  and not exists(select 1 from business_auth.sessions where session_id=p_session_id and (member_id<>g.member_id or device_id<>g.device_id)) then
  delete from auth.sessions where id=p_session_id and user_id=g.business_id;
  insert into business_auth.events(business_id,member_id,device_id,action) values(g.business_id,g.member_id,g.device_id,'failed_signin_revoked');
 end if;
 update business_auth.grants set expires_at=least(expires_at,clock_timestamp()) where id=g.id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.triniti_business_finish_signin(p_grant_id uuid, p_business_id uuid, p_session_id uuid, p_proof_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g business_auth.grants%rowtype;m public.business_access_members%rowtype;expires timestamptz;created timestamptz;
begin
 select * into g from business_auth.grants where id=p_grant_id;
 if not found or g.business_id<>p_business_id or g.proof_hash is distinct from p_proof_hash then raise exception 'BUSINESS_GRANT_REJECTED' using errcode='42501';end if;
 perform account_erasure.assert_writable(g.business_id);
 perform pg_advisory_xact_lock(hashtextextended('studio-access:'||g.business_id::text,0));
 select * into g from business_auth.grants where id=p_grant_id for update;
 if g.expires_at<=clock_timestamp() or (g.consumed_session_id is not null and g.consumed_session_id<>p_session_id) then raise exception 'BUSINESS_GRANT_EXPIRED' using errcode='42501';end if;
 if not exists(select 1 from auth.users u join public.profiles p on p.id=u.id where u.id=g.business_id and u.deleted_at is null
  and (u.banned_until is null or u.banned_until<=clock_timestamp()) and p.account_type='business' and p.deactivated_at is null) then raise exception 'BUSINESS_ACCOUNT_UNAVAILABLE' using errcode='42501';end if;
 select * into m from public.business_access_members where id=g.member_id and business_id=g.business_id and active for update;
 if not found or (g.credential_hash is not null and upper(g.credential_hash)<>upper(m.code_hash)) then raise exception 'BUSINESS_MEMBER_REVOKED' using errcode='42501';end if;
 if not exists(select 1 from public.business_devices d join business_auth.device_keys k on k.device_id=d.id where d.id=g.device_id
  and d.business_id=g.business_id and d.status='approved' and k.revoked_at is null and k.proof_hash=g.proof_hash for share of d,k) then raise exception 'BUSINESS_DEVICE_REVOKED' using errcode='42501';end if;
 if g.principal_user_id is not null then
  perform 1 from auth.sessions where id=g.principal_session_id and user_id=g.principal_user_id for share;
  perform 1 from public.business_members where business_id=g.business_id and member_id=g.principal_user_id and role='owner' for share;
  if not business_auth.owner_allowed(g.principal_user_id,g.principal_session_id,g.business_id) then raise exception 'BUSINESS_OWNER_REVOKED' using errcode='42501';end if;
 end if;
 select created_at,least(coalesce(not_after,'infinity'::timestamptz),clock_timestamp()+interval '24 hours') into created,expires
  from auth.sessions where id=p_session_id and user_id=g.business_id for update;
 if not found or created is null or created<g.created_at-interval '2 seconds' or expires<=clock_timestamp() then raise exception 'BUSINESS_SESSION_MISMATCH' using errcode='42501';end if;
 if g.principal_user_id is not null then select least(expires,coalesce(not_after,'infinity'::timestamptz)) into expires from auth.sessions where id=g.principal_session_id;end if;
 if exists(select 1 from business_auth.sessions where session_id=p_session_id and (business_id<>g.business_id or member_id<>g.member_id or device_id<>g.device_id)) then raise exception 'BUSINESS_SESSION_MISMATCH' using errcode='42501';end if;
 insert into business_auth.sessions(session_id,business_id,member_id,device_id,credential_hash,principal_user_id,principal_session_id,expires_at)
  values(p_session_id,g.business_id,g.member_id,g.device_id,g.credential_hash,g.principal_user_id,g.principal_session_id,expires)
  on conflict(session_id) do nothing;
 insert into public.studio_session_members(session_id,business_id,member_id) values(p_session_id::text,g.business_id,g.member_id)
  on conflict(session_id) do update set business_id=excluded.business_id,member_id=excluded.member_id,bound_at=clock_timestamp();
 update auth.sessions set not_after=least(coalesce(not_after,'infinity'::timestamptz),expires) where id=p_session_id;
 if g.consumed_at is null then
  update public.business_access_members set last_sign_in_at=clock_timestamp() where id=m.id;
  insert into public.business_signin_log(business_id,member_id,member_name,device_id)
   select g.business_id,m.id,m.display_name,device_id from public.business_devices where id=g.device_id;
  insert into business_auth.events(business_id,member_id,device_id,principal_user_id,action) values(g.business_id,m.id,g.device_id,g.principal_user_id,'session_bound');
  update business_auth.grants set consumed_session_id=p_session_id,consumed_at=clock_timestamp() where id=g.id;
 end if;
 if not business_auth.session_allowed(g.business_id,p_session_id) then raise exception 'BUSINESS_BINDING_REJECTED' using errcode='42501';end if;
 return jsonb_build_object('success',true,'business_id',g.business_id,'member_id',m.id,'role',m.role,'session_id',p_session_id);
end $function$

CREATE OR REPLACE FUNCTION public.triniti_business_owner_access(p_user_id uuid, p_session_id uuid, p_application_id uuid, p_device text, p_proof_hash text, p_label text, p_bootstrap_owner boolean DEFAULT false, p_business_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare biz uuid;m public.business_access_members%rowtype;d jsonb;g uuid;bootstrap_device boolean;name_value text;
begin
 if (p_application_id is null)=(p_business_id is null) then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 if p_application_id is not null then
  select j.auth_user_id into biz from admin_ops.provisions j join public.business_applications a on a.id=j.application_id
   where j.application_id=p_application_id and j.kind='business' and j.completed_at is not null and a.status='approved';
 else biz:=p_business_id;end if;
 if biz is null or not business_auth.owner_allowed(p_user_id,p_session_id,biz) then
  return jsonb_build_object('allowed',false,'error','ACTIVE_OWNER_SESSION_REQUIRED');end if;
 perform account_erasure.assert_writable(p_user_id);perform account_erasure.assert_writable(biz);
 perform pg_advisory_xact_lock(hashtextextended('studio-access:'||biz::text,0));
 perform 1 from auth.sessions where id=p_session_id and user_id=p_user_id for share;
 perform 1 from public.business_members where business_id=biz and member_id=p_user_id and role='owner' for share;
 if not business_auth.owner_allowed(p_user_id,p_session_id,biz) then return jsonb_build_object('allowed',false,'error','ACTIVE_OWNER_SESSION_REQUIRED');end if;
 if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=biz and p.account_type='business' and p.deactivated_at is null
  and u.deleted_at is null and (u.banned_until is null or u.banned_until<=clock_timestamp())) then
  return jsonb_build_object('allowed',false,'error','BUSINESS_ACCOUNT_UNAVAILABLE');end if;
 if not business_auth.rate_limit('owner:'||p_user_id::text||':'||biz::text,30) then return jsonb_build_object('allowed',false,'error','TRY_LATER');end if;
 select b.* into m from business_auth.owner_seats o join public.business_access_members b on b.id=o.member_id and b.business_id=o.business_id
  where o.business_id=biz and o.user_id=p_user_id for update of b;
 if not found then
  if not coalesce(p_bootstrap_owner,false) then return jsonb_build_object('allowed',false,'error','OWNER_BOOTSTRAP_REQUIRED','requires_owner_bootstrap',true);end if;
  if (select count(*) from public.business_access_members where business_id=biz)>=500 then return jsonb_build_object('allowed',false,'error','MEMBER_LIMIT');end if;
  select left(coalesce(nullif(btrim(full_name),''),'Business owner'),100) into name_value from public.profiles where id=p_user_id;
  insert into public.business_access_members(business_id,display_name,role,code_hash)
   values(biz,name_value,'owner',encode(extensions.digest(extensions.gen_random_bytes(32),'sha256'),'hex')) returning * into m;
  insert into business_auth.owner_seats(business_id,user_id,member_id) values(biz,p_user_id,m.id);
  insert into business_auth.events(business_id,member_id,principal_user_id,action) values(biz,m.id,p_user_id,'owner_seat_created');
 elsif not m.active then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 select coalesce(p_bootstrap_owner,false) and bootstrapped_at is null into bootstrap_device from business_auth.accounts where business_id=biz for update;
 d:=business_auth.device(biz,p_device,p_proof_hash,p_label,bootstrap_device);
 if not (d->>'allowed')::boolean then return d;end if;
 update business_auth.accounts set bootstrapped_at=coalesce(bootstrapped_at,clock_timestamp()) where business_id=biz;
 insert into business_auth.grants(business_id,member_id,device_id,proof_hash,principal_user_id,principal_session_id)
  values(biz,m.id,(d->>'device_id')::uuid,p_proof_hash,p_user_id,p_session_id) returning id into g;
 return jsonb_build_object('allowed',true,'grant_id',g,'business_id',biz,'member_id',m.id);
end $function$

CREATE OR REPLACE FUNCTION public.triniti_business_signin_check(p_handle text, p_code_hash text, p_device text, p_proof_hash text, p_label text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare biz uuid;m public.business_access_members%rowtype;d jsonb;g uuid;h text:=lower(btrim(p_handle));
begin
 if h is null or h !~ '^[a-z0-9_]{3,32}$' or p_code_hash is null or p_code_hash !~ '^[0-9a-f]{64}$'
  or length(coalesce(p_device,''))>100 then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 delete from business_auth.attempts where window_at<clock_timestamp()-interval '1 day';
 delete from business_auth.grants where expires_at<clock_timestamp()-interval '1 day';
 if not business_auth.rate_limit('business:'||h,100) or not business_auth.rate_limit('device:'||h||':'||coalesce(p_device,''),12) then
  return jsonb_build_object('allowed',false,'error','TRY_LATER');end if;
 select p.id into biz from public.profiles p join auth.users u on u.id=p.id
  where lower(p.username)=h and p.account_type='business' and p.deactivated_at is null and u.deleted_at is null
   and (u.banned_until is null or u.banned_until<=clock_timestamp());
 if biz is null then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 perform account_erasure.assert_writable(biz);
 perform pg_advisory_xact_lock(hashtextextended('studio-access:'||biz::text,0));
 select * into m from public.business_access_members where business_id=biz and active and upper(code_hash)=upper(p_code_hash) for update;
 if not found then return jsonb_build_object('allowed',false,'error','ACCESS_REJECTED');end if;
 -- Personal-owner seats only open through that owner's verified personal Auth
 -- session. Their internal random code is never a second reusable credential.
 if exists(select 1 from business_auth.owner_seats where member_id=m.id) then return jsonb_build_object('allowed',false,'error','OWNER_SIGNIN_REQUIRED');end if;
 d:=business_auth.device(biz,p_device,p_proof_hash,p_label,false);
 if not (d->>'allowed')::boolean then return d;end if;
 insert into business_auth.grants(business_id,member_id,device_id,proof_hash,credential_hash)
  values(biz,m.id,(d->>'device_id')::uuid,p_proof_hash,m.code_hash) returning id into g;
 return jsonb_build_object('allowed',true,'grant_id',g,'business_id',biz,'member_id',m.id);
end $function$

CREATE OR REPLACE FUNCTION studio_workflow.context(p_expected_user uuid DEFAULT NULL::uuid)
 RETURNS studio_workflow.actor
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a studio_workflow.actor; member_row record;
begin
 a.user_id:=auth.uid();
 if a.user_id is null or (p_expected_user is not null and p_expected_user<>a.user_id)
  or coalesce(auth.jwt()->>'is_anonymous','false')<>'false' then
  raise exception 'WORKFLOW_ACTIVE_SESSION_REQUIRED' using errcode='42501';
 end if;
 if not public.business_session_allowed() then raise exception 'WORKFLOW_ACTIVE_SESSION_REQUIRED' using errcode='42501';end if;
 perform account_erasure.assert_writable(a.user_id);
 begin a.session_id:=(auth.jwt()->>'session_id')::uuid; exception when others then a.session_id:=null; end;
 perform 1 from auth.sessions s join auth.users u on u.id=s.user_id
  where s.id=a.session_id and s.user_id=a.user_id and (s.not_after is null or s.not_after>clock_timestamp())
   and u.deleted_at is null and (u.banned_until is null or u.banned_until<=clock_timestamp()) for share of s,u;
 if not found then raise exception 'WORKFLOW_ACTIVE_SESSION_REQUIRED' using errcode='42501'; end if;
 select coalesce(p.account_type='business',false) into a.is_business from public.profiles p where p.id=a.user_id and p.deactivated_at is null for share;
 if not found then raise exception 'WORKFLOW_ACCOUNT_UNAVAILABLE' using errcode='42501'; end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('studio-access:'||a.user_id::text,0));
 if a.is_business and exists(select 1 from public.business_access_members m where m.business_id=a.user_id) then
  select m.id,m.role into member_row from public.studio_session_members s
   join public.business_access_members m on m.id=s.member_id and m.business_id=s.business_id
   where s.session_id=a.session_id::text and s.business_id=a.user_id and m.active for share of s,m;
  if not found or member_row.role not in ('owner','admin','editor','recruiter','support') then
   raise exception 'WORKFLOW_MEMBER_ACCESS_REQUIRED' using errcode='42501';
  end if;
  a.member_id:=member_row.id;a.role:=member_row.role;
 else a.role:='owner';end if;
 a.actor_id:=coalesce(a.member_id,a.user_id);
 return a;
end $function$
